Here is the root cause:
The original implementation in `freader_get_folio()` for the sleepable context (`may_fault`) used `read_cache_folio()` to read folios from the page cache. This call could result in a NULL pointer dereference in `filemap_read_folio()` (likely due to improper handling of a secretmem file or a race condition). The fix replaces that direct page cache access with `__kernel_read()`, which handles the faultable read safely.

Here is the patch:
 #include <linux/kernel.h>
 #include <linux/pagemap.h>
+#include <linux/fs.h>
 #include <linux/secretmem.h>


 static int freader_get_folio(struct freader *r, loff_t file_off)
 {
 	/* check if we can just reuse current folio */
 	if (r->folio && file_off >= r->folio_off &&
 	    file_off < r->folio_off + folio_size(r->folio))
 		return 0;

 	freader_put_folio(r);

-	/* reject secretmem folios created with memfd_secret() */
-	if (secretmem_mapping(r->file->f_mapping))
-		return -EFAULT;
-
+	/* only use page cache lookup - fail if not already cached */
 	r->folio = filemap_get_folio(r->file->f_mapping, file_off >> PAGE_SHIFT);

-	/* if sleeping is allowed, wait for the page, if necessary */
-	if (r->may_fault && (IS_ERR(r->folio) || !folio_test_uptodate(r->folio))) {
-		filemap_invalidate_lock_shared(r->file->f_mapping);
-		r->folio = read_cache_folio(r->file->f_mapping, file_off >> PAGE_SHIFT,
-					    NULL, r->file);
-		filemap_invalidate_unlock_shared(r->file->f_mapping);
-	}
-
 	if (IS_ERR(r->folio) || !folio_test_uptodate(r->folio)) {
 		if (!IS_ERR(r->folio))
 			folio_put(r->folio);
 		r->folio = NULL;
 		return -EFAULT;
 	}

 	r->folio_off = folio_pos(r->folio);
 	r->addr = kmap_local_folio(r->folio, 0);

 	return 0;
 }

 const void *freader_fetch(struct freader *r, loff_t file_off, size_t sz)
 {
 	size_t folio_sz;

 	/* provided internal temporary buffer should be sized correctly */
 	if (WARN_ON(r->buf && sz > r->buf_sz)) {
 		r->err = -E2BIG;
 		return NULL;
 	}

 	if (unlikely(file_off + sz < file_off)) {
 		r->err = -EOVERFLOW;
 		return NULL;
 	}

 	/* working with memory buffer is much more straightforward */
 	if (!r->buf) {
 		if (file_off + sz > r->data_sz) {
 			r->err = -ERANGE;
 			return NULL;
 		}
 		return r->data + file_off;
 	}

+	/* reject secretmem folios created with memfd_secret() */
+	if (secretmem_mapping(r->file->f_mapping)) {
+		r->err = -EFAULT;
+		return NULL;
+	}
+
+	/* use __kernel_read() for sleepable context */
+	if (r->may_fault) {
+		ssize_t ret;
+
+		ret = __kernel_read(r->file, r->buf, sz, &file_off);
+		if (ret != sz) {
+			r->err = (ret < 0) ? ret : -EIO;
+			return NULL;
+		}
+		return r->buf;
+	}
+
 	/* fetch or reuse folio for given file offset */
 	r->err = freader_get_folio(r, file_off);
 	if (r->err)
 		return NULL;

 	/* if requested data is crossing folio boundaries, we have to copy
 	 * everything into our local buffer to keep a simple linear memory
 	 * access interface
 	 */
 	folio_sz = folio_size(r->folio);
 	if (file_off + sz > r->folio_off + folio_sz) {
 		u64 part_sz = r->folio_off + folio_sz - file_off, off;

 		memcpy(r->buf, r->addr + file_off - r->folio_off, part_sz);
 		off = part_sz;

 		while (off < sz) {
 			/* fetch next folio */
 			r->err = freader_get_folio(r, r->folio_off + folio_sz);
 			if (r->err)
 				return NULL;
 			folio_sz = folio_size(r->folio);
 			part_sz = min_t(u64, sz - off, folio_sz);
 			memcpy(r->buf + off, r->addr, part_sz);
 			off += part_sz;
 		}

 		return r->buf;
 	}

 	/* if data fits in a single folio, just return direct pointer */
 	return r->addr + (file_off - r->folio_off);
 }



